import { errnoCode } from './errno.js';
export const PACKAGE_BUILDER_MISSING = 'The optional @mintlify/package-builder dependency is not installed, so npm packages are unavailable. npm skips it under --omit=optional or when esbuild fails to install; reinstall mint with --include=optional --foreground-scripts to see why.';
const NOT_FOUND_CODES = new Set(['ERR_MODULE_NOT_FOUND', 'MODULE_NOT_FOUND']);
export const loadPackageBuilder = async (load = () => import('@mintlify/package-builder')) => {
    try {
        return await load();
    }
    catch (error) {
        if (NOT_FOUND_CODES.has(errnoCode(error) ?? '') &&
            error instanceof Error &&
            error.message.includes("'@mintlify/package-builder'")) {
            throw new Error(PACKAGE_BUILDER_MISSING);
        }
        throw error;
    }
};
export const formatDiagnostic = ({ pkg, message }) => `${pkg ? `${pkg}: ` : ''}${message}`;
